div.script:
document.addEventListener('DOMContentLoaded', function () {
    var buttons = document.querySelectorAll('.ea-self-checkin-btn');
    if (!buttons.length) {
        return;
    }
    buttons.forEach(function (btn) {
        btn.addEventListener('click', function (ev) {
            ev.preventDefault();
            if (btn.dataset.used === '1') {
                return;
            }
            var confirmUse = window.confirm('Use this ticket now? This will self check-in and mark the ticket as used.');
            if (!confirmUse) {
                return;
            }
            var batchId = btn.dataset.batchId;
            if (!batchId) {
                return;
            }
            btn.disabled = true;
            btn.classList.add('disabled');

            fetch('/my/event-registrations/batch/' + encodeURIComponent(batchId) + '/self-checkin', {
                method: 'POST',
                credentials: 'same-origin',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({}),
            })
                .then(function (resp) {
                    if (!resp.ok) {
                        throw new Error('Server error (' + resp.status + ').');
                    }
                    return resp.text().then(function (text) {
                        try {
                            return JSON.parse(text || '{}');
                        } catch (e) {
                            // If parsing fails but response is 200, assume success (backend may have returned HTML while still marking attendance)
                            return { ok: true, parse_fallback: true };
                        }
                    });
                })
                .then(function (data) {
                    if (!data || data.ok === false) {
                        throw new Error((data && data.message) || 'Self check-in failed.');
                    }
                    btn.dataset.used = '1';
                    var label = (data.status === 'already_checked_in') ? 'Already checked-in' : 'Used';
                    btn.innerHTML = '<i class="fa fa-check-circle"></i> ' + label;
                    var card = btn.closest('.ea-ticket-card');
                    if (card) {
                        card.classList.add('ea-ticket-card--used');
                    }
                })
                .catch(function (err) {
                    alert(err.message || 'Unable to self check-in right now.');
                    btn.disabled = false;
                    btn.classList.remove('disabled');
                });
        });
    });
});


document.addEventListener('DOMContentLoaded', function() {
    try {
    const jq = window.jQuery || window.$;
    const venueTypeSelect = document.getElementById('venue_type');
    const onlineFields = document.getElementById('online_venue_fields');
    const physicalFields = document.getElementById('physical_venue_fields');
    const countrySelect = document.getElementById('country_id');
    const stateSelect = document.getElementById('state_id');
    const zipCodeInput = document.getElementById('zip_code');
    const eventNameInput = document.getElementById('event_name');
    const dateBeginInput = document.getElementById('date_begin');
    const dateEndInput = document.getElementById('date_end');
    const eventDateRangeInput = document.getElementById('event_datetimes');
    const eventDateFallback = document.getElementById('event-date-fallback');
    const badgeInput = document.getElementById('badge_image');
    const cardBgInput = document.getElementById('card_bg_image');
    const previewTitle = document.getElementById('event-card-title-preview');
    const previewDate = document.getElementById('event-card-date-preview');
    const previewBg = document.getElementById('event-card-bg-preview');
    const previewBadge = document.getElementById('event-card-badge-preview');
    const ticketLinesContainer = document.getElementById('ticket-lines-container');
    const ticketLineTemplate = document.getElementById('ticket-line-template');
    const addTicketLineBtn = document.getElementById('add-ticket-line');
    const eventImagesInput = document.getElementById('event_images');
    const imagesPreview = document.getElementById('event-images-preview');
    const thumbnailChoiceInput = document.getElementById('thumbnail_choice');
    const maxImages = 5;
    const maxImageBytes = 2 * 1024 * 1024; // 2 MB
    const maxImageLabel = '2 MB';
    const existingImagesHidden = document.getElementById('existing_image_ids');
    const existingImagesNote = document.getElementById('existing-images-note');
    const badgeExistingNote = document.getElementById('badge-existing-note');
    const limitNotice = document.getElementById('event-images-limit');
    let selectedImages = [];
    let currentThumbUrl = '';

    // Keep accessibility clean if runtime DOM changes leave orphaned labels.
    document.querySelectorAll('label[for]').forEach(function(labelEl) {
        const targetId = labelEl.getAttribute('for');
        if (targetId && !document.getElementById(targetId)) {
            labelEl.removeAttribute('for');
        }
    });

    // This script can be bundled in shared frontend assets.
    // Guard all logic when the event application form is not present.
    if (!venueTypeSelect || !onlineFields || !physicalFields) {
        return;
    }

    function toggleVenueFields() {
        if (!venueTypeSelect || !onlineFields || !physicalFields) {
            return;
        }
        const selectedType = venueTypeSelect.value;

        if (selectedType === 'online') {
            onlineFields.style.display = 'block';
            physicalFields.style.display = 'none';
            // Clear physical fields
            const venueName = document.getElementById('venue_name');
            const buildingName = document.getElementById('building_name');
            const street = document.getElementById('street_address');
            const street2 = document.getElementById('street_address2');
            const district = document.getElementById('district');
            const floor = document.getElementById('floor');
            const unitNo = document.getElementById('unit_no');
            const city = document.getElementById('city');
            const zip = document.getElementById('zip_code');
            const state = document.getElementById('state_id');
            if (venueName) venueName.value = '';
            if (buildingName) buildingName.value = '';
            if (street) street.value = '';
            if (street2) street2.value = '';
            if (district) district.value = '';
            if (floor) floor.value = '';
            if (unitNo) unitNo.value = '';
            if (city) city.value = '';
            if (zip) zip.value = '';
            if (state) state.value = '';
        } else {
            onlineFields.style.display = 'none';
            physicalFields.style.display = 'block';
            // Clear online fields
            const platform = document.getElementById('online_platform');
            const link = document.getElementById('online_link');
            if (platform) platform.value = '';
            if (link) link.value = '';
        }
    }

    function updateStates() {
        if (!countrySelect || !stateSelect) {
            return;
        }
        const selectedCountryId = countrySelect.value;
        const stateOptions = stateSelect.querySelectorAll('option');

        // Reset state selection
        stateSelect.value = '';

        // Show/hide states based on selected country
        stateOptions.forEach(option => {
            if (option.value === '') {
                option.style.display = 'block'; // Always show empty option
            } else {
                const stateCountryId = option.getAttribute('data-country');
                if (selectedCountryId && stateCountryId === selectedCountryId) {
                    option.style.display = 'block';
                } else {
                    option.style.display = 'none';
                }
            }
        });

        validateZipCode();
    }

    function validateZipCode() {
        if (!zipCodeInput || !countrySelect) {
            return;
        }
        const zipCode = zipCodeInput.value;
        const selectedCountry = countrySelect.options[countrySelect.selectedIndex]?.text;

        if (!zipCode) return; // Don't validate empty ZIP codes

        let isValid = false;
        let errorMessage = '';

        if (selectedCountry === 'United States') {
            // US ZIP code: 12345 or 12345-6789
            isValid = /^\d{5}(-\d{4})?$/.test(zipCode);
            errorMessage = 'US ZIP codes must be in format 12345 or 12345-6789';
        } else if (selectedCountry === 'Canada') {
            // Canadian postal code: A1A 1A1 or A1A1A1
            isValid = /^[A-Za-z]\d[A-Za-z]\s?\d[A-Za-z]\d$/.test(zipCode);
            errorMessage = 'Canadian postal codes must be in format A1A 1A1 or A1A1A1';
        } else {
            // For other countries, basic validation (not empty and reasonable length)
            isValid = zipCode.length >= 3 && zipCode.length <= 10;
            errorMessage = 'Please enter a valid postal code';
        }

        // Visual feedback
        zipCodeInput.classList.toggle('is-invalid', !isValid && zipCode.length > 0);
        zipCodeInput.classList.toggle('is-valid', isValid);

        // Update or create error message
        let errorElement = zipCodeInput.parentNode.querySelector('.invalid-feedback');
        if (!errorElement) {
            errorElement = document.createElement('div');
            errorElement.className = 'invalid-feedback';
            zipCodeInput.parentNode.appendChild(errorElement);
        }
        if (errorElement) {
            errorElement.textContent = errorMessage;
        }
    }

    function updatePreviewText() {
        const nameValue = eventNameInput ? eventNameInput.value.trim() : '';
        const dateValue = dateBeginInput ? dateBeginInput.value.trim() : '';
        if (previewTitle) {
            previewTitle.textContent = nameValue || 'Event name preview';
        }
        if (previewDate) {
            previewDate.textContent = dateValue ? dateValue.replace('T', ' ') : 'Start date preview';
        }
    }

    function updateThumbPreview(url) {
        if (previewBg && url) {
            previewBg.style.backgroundImage = `url(${url})`;
            previewBg.classList.add('has-preview');
        }
    }

    function renderImagePreviews(fileList) {
        if (!imagesPreview) {
            return;
        }
        const files = Array.from(fileList || []);
        imagesPreview.innerHTML = '';
        // Show existing images if no new files selected and we have stored IDs.
        if (!files.length && existingImagesHidden && existingImagesHidden.value && existingImagesHidden.dataset.cleared !== '1') {
            const ids = existingImagesHidden.value.split(',').map(id => id.trim()).filter(Boolean);
            ids.forEach((id) => {
                const col = document.createElement('div');
                col.className = 'col-6 col-md-4 col-lg-3';
                col.innerHTML = `
                    <div class="card h-100 shadow-sm">
                        <img src="/web/image/event.application.image/${id}/image/256x0" class="card-img-top" style="object-fit: cover; height: 140px;">
                        <div class="card-body p-2">
                            <div class="small text-muted text-truncate">Existing image</div>
                        </div>
                    </div>
                `;
                imagesPreview.appendChild(col);
            });
            if (existingImagesNote) {
                existingImagesNote.textContent = `Keeping ${ids.length} existing image(s). Upload new files to replace.`;
                existingImagesNote.classList.remove('d-none');
            }
        }
        if (!files.length) {
            if (thumbnailChoiceInput) {
                thumbnailChoiceInput.value = '';
            }
            if (existingImagesNote && (!existingImagesHidden || !existingImagesHidden.value || existingImagesHidden.dataset.cleared === '1')) {
                existingImagesNote.textContent = '';
                existingImagesNote.classList.add('d-none');
            }
            return;
        }
        files.forEach((file, idx) => {
            const col = document.createElement('div');
            col.className = 'col-6 col-md-4 col-lg-3';
            const wrapper = document.createElement('div');
            wrapper.className = 'p-2 bg-white border rounded shadow-sm h-100 position-relative';
            const img = document.createElement('img');
            img.className = 'ea-image-thumb mb-2';
            img.alt = file.name || `Image ${idx + 1}`;
            const reader = new FileReader();
            reader.onload = (ev) => {
                img.src = ev.target.result;
                const url = ev.target.result;
                radio.dataset.url = url;
                if (radio.checked) {
                    currentThumbUrl = url;
                    updateThumbPreview(url);
                }
            };
            reader.readAsDataURL(file);
            const thumbSelect = document.createElement('label');
            thumbSelect.className = 'ea-thumb-choice';
            const radio = document.createElement('input');
            radio.type = 'radio';
            radio.name = 'thumbnail_choice_radio';
            radio.value = idx;
            const currentChoice = parseInt(thumbnailChoiceInput?.value || '0', 10);
            radio.checked = Number.isInteger(currentChoice) ? currentChoice === idx : idx === 0;
            radio.addEventListener('change', () => {
                if (thumbnailChoiceInput) {
                    thumbnailChoiceInput.value = String(idx);
                }
                if (radio.dataset.url) {
                    currentThumbUrl = radio.dataset.url;
                    updateThumbPreview(currentThumbUrl);
                }
            });
            const text = document.createElement('span');
            text.textContent = 'Use as thumbnail';
            thumbSelect.appendChild(radio);
            thumbSelect.appendChild(text);
            const removeBtn = document.createElement('button');
            removeBtn.type = 'button';
            removeBtn.className = 'btn btn-sm btn-danger ea-thumb-remove';
            removeBtn.innerHTML = '<i class="fa fa-times"></i>';
            removeBtn.addEventListener('click', (ev) => {
                ev.preventDefault();
                selectedImages.splice(idx, 1);
                const dt = new DataTransfer();
                selectedImages.forEach(f => dt.items.add(f));
                if (eventImagesInput) {
                    eventImagesInput.files = dt.files;
                }
                // Reset thumbnail choice if necessary
               if (thumbnailChoiceInput) {
                   const newIdx = Math.min(parseInt(thumbnailChoiceInput.value || '0', 10), selectedImages.length - 1);
                   thumbnailChoiceInput.value = newIdx >= 0 ? String(newIdx) : '';
               }
               renderImagePreviews(selectedImages);
                if (limitNotice && selectedImages.length <= maxImages) {
                    limitNotice.textContent = '';
                    limitNotice.classList.add('d-none');
                }
            });
            wrapper.appendChild(img);
            wrapper.appendChild(thumbSelect);
            wrapper.appendChild(removeBtn);
            col.appendChild(wrapper);
            imagesPreview.appendChild(col);
        });
        if (thumbnailChoiceInput) {
            thumbnailChoiceInput.value = thumbnailChoiceInput.value !== '' ? thumbnailChoiceInput.value : '0';
        }
        if (limitNotice) {
            if (files.length > maxImages) {
                limitNotice.textContent = `You can upload up to ${maxImages} images. Please remove extra files.`;
                limitNotice.classList.remove('d-none');
            } else {
                limitNotice.textContent = '';
                limitNotice.classList.add('d-none');
            }
        }
    }

    function mergeImageSelections(newFileList) {
        const fresh = Array.from(newFileList || []).filter(f => f && f.name);
        if (!fresh.length) {
            return;
        }
        const allowed = [];
        const rejected = [];
        fresh.forEach(function(file) {
            if (file.size && file.size > maxImageBytes) {
                rejected.push(file.name);
                return;
            }
            allowed.push(file);
        });
        const available = Math.max(0, maxImages - selectedImages.length);
        let toAdd = allowed;
        if (allowed.length > available) {
            toAdd = allowed.slice(0, available);
            if (limitNotice) {
                limitNotice.textContent = `You can upload up to ${maxImages} images. Only the first ${available} new file(s) were kept.`;
                limitNotice.classList.remove('d-none');
            }
        }
        if (limitNotice) {
            if (rejected.length) {
                limitNotice.textContent = `Skipped ${rejected.length} file(s) over ${maxImageLabel}: ${rejected.join(', ')}`;
                limitNotice.classList.remove('d-none');
            } else if (toAdd.length <= available) {
                limitNotice.textContent = '';
                limitNotice.classList.add('d-none');
            }
        }
        // When new files are selected, ignore existing stored images
        if (existingImagesHidden) {
            existingImagesHidden.dataset.cleared = '1';
            if (existingImagesNote) {
                existingImagesNote.textContent = '';
                existingImagesNote.classList.add('d-none');
            }
        }
        // Keep previously chosen files and append within limit.
        selectedImages = selectedImages.concat(toAdd).slice(0, maxImages);
        // Rebuild the input's FileList so it submits all accumulated files.
        const dt = new DataTransfer();
        selectedImages.forEach(file => dt.items.add(file));
        if (eventImagesInput) {
            eventImagesInput.files = dt.files;
        }
        renderImagePreviews(selectedImages);
    }

    function initEventDateRangePicker() {
        if (!eventDateRangeInput || !dateBeginInput || !dateEndInput) {
            return;
        }
        const hasPicker = function() {
            const localJq = window.jQuery || window.$;
            return Boolean(
                localJq &&
                window.moment &&
                localJq.fn &&
                typeof localJq.fn.daterangepicker === 'function'
            );
        };
        const showFallback = function() {
            // Keep merged field only; do not show separate start/end controls.
            dateBeginInput.required = false;
            dateEndInput.required = false;
            eventDateRangeInput.required = true;
        };
        const activateRangePicker = function() {
            const localJq = window.jQuery || window.$;
            if (!hasPicker()) {
                return false;
            }

        if (eventDateFallback) {
            eventDateFallback.classList.add('d-none');
        }
        dateBeginInput.required = false;
        dateEndInput.required = false;
        eventDateRangeInput.required = true;
        eventDateRangeInput.classList.remove('d-none');

        let start = dateBeginInput.value ? window.moment(dateBeginInput.value) : window.moment().startOf('hour');
        let end = dateEndInput.value ? window.moment(dateEndInput.value) : start.clone().add(32, 'hour');
        if (!start.isValid()) {
            start = window.moment().startOf('hour');
        }
        if (!end.isValid() || end.isBefore(start)) {
            end = start.clone().add(32, 'hour');
        }

        const syncDateRange = function(startDate, endDate) {
            dateBeginInput.value = startDate.format('YYYY-MM-DDTHH:mm');
            dateEndInput.value = endDate.format('YYYY-MM-DDTHH:mm');
            eventDateRangeInput.value = `${startDate.format('M/DD hh:mm A')} - ${endDate.format('M/DD hh:mm A')}`;
            updatePreviewText();
        };

        localJq(eventDateRangeInput).daterangepicker({
            timePicker: true,
            startDate: start,
            endDate: end,
            locale: {
                format: 'M/DD hh:mm A'
            }
        }, function(startDate, endDate) {
            syncDateRange(startDate, endDate);
        });

        syncDateRange(start, end);
            return true;
        };

        if (activateRangePicker()) {
            return;
        }
        let tries = 0;
        const retryTimer = window.setInterval(function() {
            tries += 1;
            if (activateRangePicker()) {
                window.clearInterval(retryTimer);
                return;
            }
            if (tries >= 10) {
                window.clearInterval(retryTimer);
                showFallback();
            }
        }, 100);
    }

    function updatePreviewImage(input, target, isBackground) {
        const file = input.files && input.files[0];
        if (!file) {
            if (isBackground) {
                target.style.backgroundImage = '';
            } else {
                target.style.display = 'none';
                target.removeAttribute('src');
            }
            return;
        }
        if (file.size && file.size > maxImageBytes) {
            if (limitNotice) {
                limitNotice.textContent = `Each image must be ${maxImageLabel} or smaller. '${file.name}' was skipped.`;
                limitNotice.classList.remove('d-none');
            }
            input.value = '';
            return;
        }
        const reader = new FileReader();
        reader.onload = function(evt) {
            if (isBackground) {
                target.style.backgroundImage = `url(${evt.target.result})`;
            } else {
                target.src = evt.target.result;
                target.style.display = 'block';
            }
        };
        reader.readAsDataURL(file);
    }

    let dateAssetsPromise = null;

    function ensureDateAssets() {
        const ready = Boolean(
            (window.jQuery || window.$) &&
            window.moment &&
            (window.jQuery || window.$).fn &&
            typeof (window.jQuery || window.$).fn.daterangepicker === 'function'
        );
        if (ready) {
            return Promise.resolve();
        }
        if (dateAssetsPromise) {
            return dateAssetsPromise;
        }
        dateAssetsPromise = new Promise((resolve, reject) => {
            const head = document.head || document.getElementsByTagName('head')[0];
            const addScript = (src) => new Promise((res, rej) => {
                const s = document.createElement('script');
                s.src = src;
                s.onload = res;
                s.onerror = rej;
                head.appendChild(s);
            });
            const addCss = (href) => {
                const l = document.createElement('link');
                l.rel = 'stylesheet';
                l.href = href;
                head.appendChild(l);
            };
            // Ensure CSS once
            if (!document.querySelector('link[href*=\"daterangepicker.css\"]')) {
                addCss('https://cdn.jsdelivr.net/npm/daterangepicker/daterangepicker.css');
            }
            // Load moment then daterangepicker
            addScript('https://cdn.jsdelivr.net/npm/moment@2.30.1/moment.min.js')
                .then(() => addScript('https://cdn.jsdelivr.net/npm/daterangepicker/daterangepicker.min.js'))
                .then(resolve)
                .catch(reject);
        });
        return dateAssetsPromise;
    }

    function bindTicketRow(row, opts) {
        const options = opts || {};
        const forceReinit = Boolean(options.forceReinit);
        const showOnInit = Boolean(options.show && false); // force disable auto-open
        if (!row) {
            return;
        }
        const limitSelect = row.querySelector('.ticket-limit-select');
        const maxInput = row.querySelector('.ticket-max-input');
        const removeBtn = row.querySelector('.remove-ticket-line');
        const ticketRangeInput = row.querySelector('.ticket-datetime-range');
        const ticketStartInput = row.querySelector('.ticket-start-input');
        const ticketEndInput = row.querySelector('.ticket-end-input');
        const ticketDateFallback = row.querySelector('.ticket-date-fallback');
        const ticketStartFallback = row.querySelector('.ticket-start-fallback');
        const ticketEndFallback = row.querySelector('.ticket-end-fallback');

        function initTicketDateRange(config) {
            const cfg = config || {};
            const forceShow = Boolean(cfg.show);
            const forceReload = Boolean(cfg.forceReinit);
            if (!ticketRangeInput || !ticketStartInput || !ticketEndInput) {
                return;
            }
            if (!ticketRangeInput.dataset.rangeRetryStarted) {
                ticketRangeInput.dataset.rangeRetryStarted = '0';
            }
            const activate = function() {
                const localJq = window.jQuery || window.$;
                const hasPicker = Boolean(
                    localJq &&
                    window.moment &&
                    localJq.fn &&
                    typeof localJq.fn.daterangepicker === 'function'
                );
                if (!hasPicker) {
                    ticketRangeInput.classList.remove('d-none');
                    if (ticketDateFallback) {
                        ticketDateFallback.classList.remove('d-none');
                    }
                    if (ticketStartFallback && ticketEndFallback) {
                        ticketStartFallback.addEventListener('change', function() {
                            ticketStartInput.value = ticketStartFallback.value;
                        });
                        ticketEndFallback.addEventListener('change', function() {
                            ticketEndInput.value = ticketEndFallback.value;
                        });
                    }
                    return;
                }

                if (ticketDateFallback) {
                    ticketDateFallback.classList.add('d-none');
                }
                ticketRangeInput.classList.remove('d-none');
                let existingPicker = localJq(ticketRangeInput).data('daterangepicker');
                if (existingPicker && forceShow) {
                    existingPicker.remove();
                    localJq(ticketRangeInput).data('daterangepicker', null);
                    existingPicker = null;
                    ticketRangeInput.dataset.rangeInit = '';
                }
                if (ticketRangeInput.dataset.rangeInit === '1' && !existingPicker) {
                    ticketRangeInput.dataset.rangeInit = '';
                }
                if (forceReload && existingPicker) {
                    existingPicker.remove();
                    localJq(ticketRangeInput).data('daterangepicker', null);
                    existingPicker = null;
                    ticketRangeInput.dataset.rangeInit = '';
                }
                if (ticketRangeInput.dataset.rangeInit === '1' && existingPicker) {
                    if (forceShow && existingPicker.show) {
                        existingPicker.show();
                    } else if (!forceShow && existingPicker.hide) {
                        existingPicker.hide();
                    }
                    return existingPicker;
                }

                const hasExistingRange = Boolean(ticketStartInput.value && ticketEndInput.value);
                let start = ticketStartInput.value ? window.moment(ticketStartInput.value) : window.moment().startOf('hour');
                let end = ticketEndInput.value ? window.moment(ticketEndInput.value) : start.clone().add(1, 'day');
                if (!start.isValid()) {
                    start = window.moment().startOf('hour');
                }
                if (!end.isValid() || end.isBefore(start)) {
                    end = start.clone().add(1, 'day');
                }

                const syncValues = function(startDate, endDate) {
                    ticketStartInput.value = startDate.format('YYYY-MM-DDTHH:mm');
                    ticketEndInput.value = endDate.format('YYYY-MM-DDTHH:mm');
                    ticketRangeInput.value = `${startDate.format('M/DD hh:mm A')} - ${endDate.format('M/DD hh:mm A')}`;
                };

                localJq(ticketRangeInput).daterangepicker({
                    timePicker: true,
                    startDate: start,
                    endDate: end,
                    autoUpdateInput: false,
                    locale: {
                        format: 'M/DD hh:mm A'
                    }
                });

                localJq(ticketRangeInput).off('apply.daterangepicker.ticket').on('apply.daterangepicker.ticket', function(ev, picker) {
                    syncValues(picker.startDate, picker.endDate);
                });
                localJq(ticketRangeInput)
                    .off('click.daterangepicker.ticketopen focus.daterangepicker.ticketopen')
                    .on('click.daterangepicker.ticketopen focus.daterangepicker.ticketopen', function() {
                        const picker = initTicketDateRange(true) || localJq(this).data('daterangepicker');
                        if (picker && picker.show) {
                            picker.show();
                        }
                    });
                // belt-and-suspenders: re-fire shortly after click/focus to catch late-loading assets
                if (forceShow) {
                    window.setTimeout(function() {
                        const latePicker = initTicketDateRange(true);
                        if (latePicker && latePicker.show) {
                            latePicker.show();
                        }
                    }, 150);
                }

                if (hasExistingRange) {
                    syncValues(start, end);
                } else {
                    ticketRangeInput.value = '';
                    ticketStartInput.value = '';
                    ticketEndInput.value = '';
                    if (ticketStartFallback) ticketStartFallback.value = '';
                    if (ticketEndFallback) ticketEndFallback.value = '';
                }
                ticketRangeInput.dataset.rangeInit = '1';
                const newPicker = localJq(ticketRangeInput).data('daterangepicker');
                if (forceShow && newPicker && newPicker.show) {
                    newPicker.show();
                } else if (!forceShow && newPicker && newPicker.hide) {
                    newPicker.hide(); // ensure closed after init
                }
                return newPicker;
            };
            ensureDateAssets().then(activate).catch(function() {
                // If assets fail, fall back to native controls
                if (ticketDateFallback) {
                    ticketDateFallback.classList.remove('d-none');
                }
            });
        }

        function syncLimitState() {
            const limited = limitSelect && limitSelect.value === '1';
            if (maxInput) {
                maxInput.disabled = !limited;
                if (!limited) {
                    maxInput.value = '';
                }
            }
        }

        if (limitSelect) {
            limitSelect.addEventListener('change', syncLimitState);
            syncLimitState();
        }
        initTicketDateRange({ show: showOnInit, forceReinit: forceReinit });
        if (ticketRangeInput) {
            ticketRangeInput.addEventListener('focus', function() {
                initTicketDateRange({ show: false, forceReinit: false });
            });
            ticketRangeInput.addEventListener('click', function() {
                initTicketDateRange({ show: true, forceReinit: false });
            });
            // Bind without showing
            initTicketDateRange({ show: false, forceReinit: forceReinit });
        }
        if (ticketStartFallback && ticketEndFallback) {
            ticketStartFallback.addEventListener('change', function() {
                ticketStartInput.value = ticketStartFallback.value;
            });
            ticketEndFallback.addEventListener('change', function() {
                ticketEndInput.value = ticketEndFallback.value;
            });
        }

        if (removeBtn) {
            removeBtn.addEventListener('click', function() {
                if (!ticketLinesContainer) {
                    return;
                }
                const rows = ticketLinesContainer.querySelectorAll('.ticket-line');
                if (rows.length <= 1) {
                    row.querySelectorAll('input').forEach(function(input) {
                        if (input.type === 'number') {
                            input.value = input.name === 'ticket_points[]' ? '0' : '';
                        } else {
                            input.value = '';
                        }
                    });
                    if (ticketRangeInput) {
                        ticketRangeInput.value = '';
                    }
                    if (limitSelect) {
                        limitSelect.value = '0';
                    }
                    syncLimitState();
                    return;
                }
                row.remove();
            });
        }
    }

    // Event listeners
    if (venueTypeSelect) venueTypeSelect.addEventListener('change', toggleVenueFields);
    if (countrySelect) countrySelect.addEventListener('change', updateStates);
    if (stateSelect) stateSelect.addEventListener('change', validateZipCode);
    if (zipCodeInput) zipCodeInput.addEventListener('input', validateZipCode);
    if (eventNameInput) eventNameInput.addEventListener('input', updatePreviewText);
    if (dateBeginInput) dateBeginInput.addEventListener('input', updatePreviewText);
    if (dateEndInput) dateEndInput.addEventListener('input', updatePreviewText);
    if (badgeInput && previewBadge) badgeInput.addEventListener('change', () => updatePreviewImage(badgeInput, previewBadge, false));
    if (cardBgInput && previewBg) cardBgInput.addEventListener('change', () => updatePreviewImage(cardBgInput, previewBg, true));
    if (eventImagesInput) {
        eventImagesInput.addEventListener('change', () => {
            mergeImageSelections(eventImagesInput.files);
        });
    }
    function kickTicketRanges(forceShow) {
        document.querySelectorAll('#ticket-lines-container .ticket-line').forEach(function(row) {
            bindTicketRow(row, { show: Boolean(forceShow), forceReinit: false });
        });
    }

    if (addTicketLineBtn && ticketLineTemplate && ticketLinesContainer) {
        addTicketLineBtn.addEventListener('click', function() {
            const newRow = appendNewTicketRow();
            if (typeof saveDraft === 'function') {
                saveDraft();
            }
            // Bind picker for the new row without auto-opening
            window.setTimeout(function() { bindTicketRow(newRow, { forceReinit: true, show: false }); }, 0);
        });
        kickTicketRanges(false);
    }
    // Initial render for images (helps when browser retains file list on back navigation)
    if (eventImagesInput && eventImagesInput.files && eventImagesInput.files.length) {
        selectedImages = Array.from(eventImagesInput.files);
        renderImagePreviews(selectedImages);
    }

    // Specialty and Case multi-select functionality
    const specialtyTags = document.getElementById('specialty-tags');
    const specialtySelect = document.getElementById('specialty-select');
    const specialtyIdsHidden = document.getElementById('specialty-ids-hidden');
    const specialtyOtherWrapper = document.getElementById('specialty-other-wrapper');
    const specialtyOtherInput = document.getElementById('specialty-other-input');

    const caseTags = document.getElementById('case-tags');
    const caseSelect = document.getElementById('case-select');
    const caseIdsHidden = document.getElementById('case-ids-hidden');
    const caseOtherWrapper = document.getElementById('case-other-wrapper');
    const caseOtherInput = document.getElementById('case-other-input');

    let selectedSpecialties = [];
    let selectedCases = [];

    function createMultiSelect(tagsContainer, select, hiddenInput, selectedItems) {
        if (!tagsContainer || !select || !hiddenInput) {
            return;
        }
        // Get all available options from the select element
        const allOptions = Array.from(select.querySelectorAll('option'))
            .map(opt => ({ rawId: opt.value, name: opt.textContent }))
            .filter(opt => /^\d+$/.test(opt.rawId))
            .map(opt => ({
                id: parseInt(opt.rawId, 10),
                name: opt.name
            }));
        const placeholder = select.dataset.placeholder || 'Select...';

        function updateSelectOptions() {
            // Clear current options except the placeholder
            select.innerHTML = `<option value="">${placeholder}</option>`;

            // Add available options (not selected)
            allOptions.forEach(option => {
                if (!selectedItems.find(selected => selected.id === option.id)) {
                    const opt = document.createElement('option');
                    if (opt) {
                        opt.value = option.id;
                        opt.textContent = option.name;
                        select.appendChild(opt);
                    }
                }
            });
            const otherOpt = document.createElement('option');
            if (otherOpt) {
                otherOpt.value = '__other__';
                otherOpt.textContent = 'Other...';
                select.appendChild(otherOpt);
            }
        }

        function updateTags() {
            tagsContainer.innerHTML = '';
            selectedItems.forEach(item => {
                const tag = document.createElement('span');
                tag.className = 'tag';
                tag.innerHTML = `${item.name} <span class="remove-tag" data-id="${item.id}">&times;</span>`;
                tagsContainer.appendChild(tag);
            });
            hiddenInput.value = selectedItems.map(item => item.id).join(',');
        }

        // Initial setup
        updateSelectOptions();
        updateTags();

        // Handle select change
        select.addEventListener('change', () => {
            if (select.value === '__other__') {
                if (select.id === 'specialty-select' && specialtyOtherWrapper) {
                    specialtyOtherWrapper.classList.remove('d-none');
                    specialtyOtherInput && specialtyOtherInput.focus();
                }
                if (select.id === 'case-select' && caseOtherWrapper) {
                    caseOtherWrapper.classList.remove('d-none');
                    caseOtherInput && caseOtherInput.focus();
                }
                select.value = '';
                return;
            }
            const selectedId = parseInt(select.value);
            if (selectedId) {
                const selectedOption = allOptions.find(opt => opt.id === selectedId);
                if (selectedOption && !selectedItems.find(item => item.id === selectedId)) {
                    selectedItems.push(selectedOption);
                    updateTags();
                    updateSelectOptions();
                }
            }
            select.value = ''; // Reset to placeholder
        });

        // Handle tag removal
        tagsContainer.addEventListener('click', (e) => {
            if (e.target.classList.contains('remove-tag')) {
                const id = parseInt(e.target.getAttribute('data-id'));
                const index = selectedItems.findIndex(item => item.id === id);
                if (index > -1) {
                    selectedItems.splice(index, 1);
                    updateTags();
                    updateSelectOptions();
                }
            }
        });
    }

    createMultiSelect(specialtyTags, specialtySelect, specialtyIdsHidden, selectedSpecialties);
    createMultiSelect(caseTags, caseSelect, caseIdsHidden, selectedCases);

    const applicationForm = document.getElementById('event-application-submit-form');
    const draftStorageKey = 'event_application_form_draft_v1';

    function getClientErrorBox() {
        if (!applicationForm) {
            return null;
        }
        let box = applicationForm.querySelector('#event-application-client-error');
        if (!box) {
            box = document.createElement('div');
            box.id = 'event-application-client-error';
            box.className = 'alert alert-danger d-none';
            applicationForm.prepend(box);
        }
        return box;
    }

    function showClientError(message) {
        const box = getClientErrorBox();
        if (!box) {
            return;
        }
        box.textContent = message || 'Please fix the form and try again.';
        box.classList.remove('d-none');
        box.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }

    function clearClientError() {
        const box = getClientErrorBox();
        if (!box) {
            return;
        }
        box.textContent = '';
        box.classList.add('d-none');
    }

    function getFieldValueByName(name, index) {
        if (!applicationForm) {
            return '';
        }
        const fields = applicationForm.querySelectorAll(`[name="${name}"]`);
        const field = fields[index];
        if (!field) {
            return '';
        }
        return (field.value || '').trim();
    }

    function validateBeforeSubmit() {
        clearClientError();
        if (!applicationForm) {
            return true;
        }
        const eventName = (eventNameInput && eventNameInput.value || '').trim();
        const dateBegin = (dateBeginInput && dateBeginInput.value || '').trim();
        const dateEndInput = document.getElementById('date_end');
        const dateEnd = (dateEndInput && dateEndInput.value || '').trim();
        if (!eventName) {
            showClientError('Event name is required.');
            return false;
        }
        if (!dateBegin || !dateEnd) {
            showClientError('Start date and end date are required.');
            return false;
        }
        if (dateBegin > dateEnd) {
            showClientError('Start date must be before end date.');
            return false;
        }

        const ticketRows = applicationForm.querySelectorAll('#ticket-lines-container .ticket-line');
        for (let i = 0; i < ticketRows.length; i++) {
            const ticketName = getFieldValueByName('ticket_name[]', i);
            const ticketStart = getFieldValueByName('ticket_start[]', i);
            const ticketEnd = getFieldValueByName('ticket_end[]', i);
            const limitQty = getFieldValueByName('ticket_limit[]', i);
            const maxQty = getFieldValueByName('ticket_max[]', i);
            const pointCost = getFieldValueByName('ticket_points[]', i);
            const hasRowData = Boolean(ticketName || ticketStart || ticketEnd || maxQty || (pointCost && pointCost !== '0'));
            if (!hasRowData) {
                continue;
            }
            if (!ticketName) {
                showClientError(`Ticket ${i + 1}: ticket name is required.`);
                return false;
            }
            if (ticketStart && ticketEnd && ticketStart > ticketEnd) {
                showClientError(`Ticket ${i + 1}: sales start must be before sales end.`);
                return false;
            }
            if (limitQty === '1' && (!maxQty || parseInt(maxQty, 10) <= 0)) {
                showClientError(`Ticket ${i + 1}: max quantity must be greater than 0 when limit is enabled.`);
                return false;
            }
            if (pointCost && parseInt(pointCost, 10) < 0) {
                showClientError(`Ticket ${i + 1}: point cost cannot be negative.`);
                return false;
            }
        }
        return true;
    }

    function buildDraftPayload() {
        if (!applicationForm) {
            return null;
        }
        const payload = {};
        const fields = applicationForm.querySelectorAll('input, textarea, select');
        fields.forEach((field) => {
            const name = field.name;
            if (!name || name === 'csrf_token' || field.type === 'file') {
                return;
            }
            if ((field.type === 'checkbox' || field.type === 'radio') && !field.checked) {
                return;
            }
            if (name.endsWith('[]')) {
                if (!Array.isArray(payload[name])) {
                    payload[name] = [];
                }
                payload[name].push(field.value || '');
            } else {
                payload[name] = field.value || '';
            }
        });
        return payload;
    }

    function restoreDraftPayload(payload) {
        if (!applicationForm || !payload) {
            return;
        }
        const ticketArrays = ['ticket_name[]', 'ticket_start[]', 'ticket_end[]', 'ticket_limit[]', 'ticket_max[]', 'ticket_points[]'];
        const targetRows = Math.max(
            ...ticketArrays.map((key) => Array.isArray(payload[key]) ? payload[key].length : 0),
            1
        );
        let guard = 0;
        while (ticketLinesContainer && ticketLinesContainer.querySelectorAll('.ticket-line').length < targetRows && guard < 100) {
            const created = appendNewTicketRow();
            if (!created) {
                break;
            }
            guard += 1;
        }
        Object.keys(payload).forEach((name) => {
            const value = payload[name];
            const fields = applicationForm.querySelectorAll(`[name="${name}"]`);
            if (!fields.length) {
                return;
            }
            if (Array.isArray(value)) {
                value.forEach((entry, idx) => {
                    if (fields[idx]) {
                        fields[idx].value = entry;
                    }
                });
            } else {
                fields[0].value = value;
            }
        });
        if (existingImagesHidden && payload.existing_image_ids) {
            existingImagesHidden.value = payload.existing_image_ids;
            existingImagesHidden.dataset.cleared = '0';
            renderImagePreviews([]);
        }
        if (payload.specialty_id_list && specialtySelect) {
            const ids = Array.isArray(payload.specialty_id_list) ? payload.specialty_id_list : String(payload.specialty_id_list).split(',').map(x => x.trim()).filter(Boolean);
            ids.forEach((id) => {
                const option = specialtySelect.querySelector(`option[value="${id}"]`);
                if (option) {
                    option.selected = true;
                }
            });
            specialtySelect.dispatchEvent(new Event('change'));
        }
        if (payload.case_id_list && caseSelect) {
            const ids = Array.isArray(payload.case_id_list) ? payload.case_id_list : String(payload.case_id_list).split(',').map(x => x.trim()).filter(Boolean);
            ids.forEach((id) => {
                const option = caseSelect.querySelector(`option[value="${id}"]`);
                if (option) {
                    option.selected = true;
                }
            });
            caseSelect.dispatchEvent(new Event('change'));
        }
        if (payload.thumbnail_image_url) {
            currentThumbUrl = payload.thumbnail_image_url;
            updateThumbPreview(currentThumbUrl);
        }
        if (payload.badge_image_url && previewBadge) {
            previewBadge.src = payload.badge_image_url;
            previewBadge.style.display = 'block';
            if (badgeExistingNote) {
                badgeExistingNote.textContent = 'Keeping existing badge background. Upload a new image to replace.';
                badgeExistingNote.classList.remove('d-none');
            }
        } else if (badgeExistingNote) {
            badgeExistingNote.textContent = '';
            badgeExistingNote.classList.add('d-none');
        }
        // Restore thumbnail (card background) preference
        if (payload.thumbnail_image_url) {
            currentThumbUrl = payload.thumbnail_image_url;
            updateThumbPreview(currentThumbUrl);
        } else if (existingImagesHidden && existingImagesHidden.value && existingImagesHidden.dataset.cleared !== '1') {
            const firstExistingId = existingImagesHidden.value.split(',').map(id => id.trim()).filter(Boolean)[0];
            if (firstExistingId) {
                currentThumbUrl = `/web/image/event.application.image/${firstExistingId}/image/720x0`;
                updateThumbPreview(currentThumbUrl);
            }
        }
        if (ticketLinesContainer) {
            ticketLinesContainer.querySelectorAll('.ticket-line').forEach(function(row) {
                bindTicketRow(row);
            });
        }
        toggleVenueFields();
        updateStates();
        updatePreviewText();
    }

    function saveDraft() {
        const payload = buildDraftPayload();
        if (!payload) {
            return;
        }
        sessionStorage.setItem(draftStorageKey, JSON.stringify(payload));
    }

    function restoreDraft() {
        const raw = sessionStorage.getItem(draftStorageKey);
        if (!raw) {
            return;
        }
        try {
            restoreDraftPayload(JSON.parse(raw));
        } catch (_) {
            sessionStorage.removeItem(draftStorageKey);
        }
    }

    function appendNewTicketRow() {
        if (!ticketLineTemplate || !ticketLinesContainer) {
            return null;
        }
        const templateRow = ticketLineTemplate.querySelector('.ticket-line');
        if (!templateRow) {
            return null;
        }
        const newRow = templateRow.cloneNode(true);
        // Ensure cloned row never carries stale picker/value state.
        newRow.querySelectorAll('input').forEach(function(input) {
            input.value = '';
        });
        const newRangeInput = newRow.querySelector('.ticket-datetime-range');
        if (newRangeInput) {
            newRangeInput.dataset.rangeInit = '';
            newRangeInput.dataset.rangeRetryStarted = '0';
        }
        ticketLinesContainer.appendChild(newRow);
        bindTicketRow(newRow, { show: false, forceReinit: true });
        // Kick the date-range picker once the row is in the DOM so the control opens reliably.
        if (newRangeInput) {
            const triggerInit = function() {
                newRangeInput.dispatchEvent(new Event('focus', { bubbles: true }));
                newRangeInput.dispatchEvent(new Event('click', { bubbles: true }));
            };
            if (window.requestAnimationFrame) {
                window.requestAnimationFrame(triggerInit);
            } else {
                window.setTimeout(triggerInit, 0);
            }
        }
        return newRow;
    }

    if (applicationForm) {
        restoreDraft();
        applicationForm.addEventListener('input', saveDraft);
        applicationForm.addEventListener('change', saveDraft);
        applicationForm.addEventListener('submit', function (ev) {
            if (!validateBeforeSubmit()) {
                ev.preventDefault();
                return;
            }
            const submitBtn = applicationForm.querySelector('button[type="submit"]');
            if (submitBtn) {
                submitBtn.disabled = true;
                submitBtn.textContent = 'Validating...';
            }
            saveDraft();
        });
    }


    // Initialize
    initEventDateRangePicker();
    if (venueTypeSelect && onlineFields && physicalFields) toggleVenueFields();
    if (countrySelect && stateSelect) updateStates();
    if (eventNameInput || dateBeginInput || previewTitle || previewDate) updatePreviewText();
    } catch (err) {
        console.error('event_application form init failed', err);
    }
});

t.script:

window.addEventListener('pageshow', function (event) {
    const navEntry = (performance.getEntriesByType && performance.getEntriesByType('navigation')[0]) || null;
    const fromBackForward = navEntry && navEntry.type === 'back_forward';
    if (event.persisted || fromBackForward) {
        window.location.reload();
    }
});
// Handle draft delete via fetch to avoid navigation
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.ea-app-delete-form').forEach(function(form) {
        form.addEventListener('submit', function(ev) {
            ev.preventDefault();
            if (!window.confirm('Delete this draft application?')) {
                return;
            }
            const action = form.getAttribute('action');
            const csrf = form.querySelector('input[name="csrf_token"]')?.value || '';
            fetch(action, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                },
                body: `csrf_token=${encodeURIComponent(csrf)}`,
            }).then(function(resp) {
                if (resp.ok) {
                    window.location.reload();
                } else {
                    alert('Failed to delete draft. Please try again.');
                }
            }).catch(function() {
                alert('Failed to delete draft. Please try again.');
            });
        });
    });
});

(function() {
    try {
        const payload = JSON.parse(atob(''));
        sessionStorage.setItem('event_application_form_draft_v1', JSON.stringify(payload));
    } catch (e) {
        console.error('Failed to restore draft for resubmission', e);
    }
    window.location.href = '/event/apply';
})();

div.script:

document.addEventListener('DOMContentLoaded', function () {
    const jq = window.jQuery || window.$;
    const rangeInput = document.getElementById('event_edit_datetimes');
    const beginInput = document.getElementById('date_begin');
    const endInput = document.getElementById('date_end');
    const fallbackBox = document.getElementById('event-edit-date-fallback');
    if (!rangeInput || !beginInput || !endInput) {
        return;
    }

    const hasPicker = Boolean(
        jq &&
        window.moment &&
        jq.fn &&
        typeof jq.fn.daterangepicker === 'function'
    );
    const initPicker = function () {
        const localJq = window.jQuery || window.$;
        const ready = Boolean(
            localJq &&
            window.moment &&
            localJq.fn &&
            typeof localJq.fn.daterangepicker === 'function'
        );
        if (!ready) {
            return false;
        }
        beginInput.required = false;
        endInput.required = false;
        rangeInput.required = true;
        if (fallbackBox) {
            fallbackBox.classList.add('d-none');
        }
        rangeInput.classList.remove('d-none');

        let start = beginInput.value ? window.moment(beginInput.value) : window.moment().startOf('hour');
        let end = endInput.value ? window.moment(endInput.value) : start.clone().add(32, 'hour');
        if (!start.isValid()) {
            start = window.moment().startOf('hour');
        }
        if (!end.isValid() || end.isBefore(start)) {
            end = start.clone().add(32, 'hour');
        }

        const sync = function (s, e) {
            beginInput.value = s.format('YYYY-MM-DDTHH:mm');
            endInput.value = e.format('YYYY-MM-DDTHH:mm');
            rangeInput.value = `${s.format('M/DD hh:mm A')} - ${e.format('M/DD hh:mm A')}`;
        };

        localJq(rangeInput).daterangepicker({
            timePicker: true,
            startDate: start,
            endDate: end,
            locale: { format: 'M/DD hh:mm A' }
        }, function (s, e) {
            sync(s, e);
        });
        sync(start, end);
        return true;
    };

    if (!initPicker()) {
        let tries = 0;
        const retryTimer = window.setInterval(function () {
            tries += 1;
            if (initPicker()) {
                window.clearInterval(retryTimer);
                return;
            }
            if (tries >= 10) {
                window.clearInterval(retryTimer);
            }
        }, 100);
    }

    const initTicketPickers = function () {
        const localJq = window.jQuery || window.$;
        const ready = Boolean(
            localJq &&
            window.moment &&
            localJq.fn &&
            typeof localJq.fn.daterangepicker === 'function'
        );
        if (!ready) {
            return false;
        }
        const ticketRanges = document.querySelectorAll('.ticket-edit-datetime-range');
        ticketRanges.forEach(function (rangeEl) {
            const ticketId = rangeEl.getAttribute('data-ticket-id');
            if (!ticketId || rangeEl.dataset.rangeInit === '1') {
                return;
            }
            const startEl = document.querySelector(`.ticket-edit-start[data-ticket-id="${ticketId}"]`);
            const endEl = document.querySelector(`.ticket-edit-end[data-ticket-id="${ticketId}"]`);
            if (!startEl || !endEl) {
                return;
            }
            let start = startEl.value ? window.moment(startEl.value) : window.moment().startOf('hour');
            let end = endEl.value ? window.moment(endEl.value) : start.clone().add(1, 'day');
            if (!start.isValid()) {
                start = window.moment().startOf('hour');
            }
            if (!end.isValid() || end.isBefore(start)) {
                end = start.clone().add(1, 'day');
            }
            const sync = function (s, e) {
                startEl.value = s.format('YYYY-MM-DDTHH:mm');
                endEl.value = e.format('YYYY-MM-DDTHH:mm');
                rangeEl.value = `${s.format('M/DD hh:mm A')} - ${e.format('M/DD hh:mm A')}`;
            };
            localJq(rangeEl).daterangepicker({
                timePicker: true,
                startDate: start,
                endDate: end,
                locale: { format: 'M/DD hh:mm A' }
            }, function (s, e) {
                sync(s, e);
            });
            sync(start, end);
            rangeEl.dataset.rangeInit = '1';
        });
        return true;
    };

    if (!initTicketPickers()) {
        let ticketTries = 0;
        const ticketRetryTimer = window.setInterval(function () {
            ticketTries += 1;
            if (initTicketPickers()) {
                window.clearInterval(ticketRetryTimer);
                return;
            }
            if (ticketTries >= 10) {
                window.clearInterval(ticketRetryTimer);
            }
        }, 100);
    }

    const initOtherDynamicList = function (listId, hiddenId) {
        const listEl = document.getElementById(listId);
        const hiddenEl = document.getElementById(hiddenId);
        if (!listEl || !hiddenEl) {
            return;
        }

        const parseExisting = function () {
            const raw = (listEl.dataset.existing || '').trim();
            if (!raw) {
                return [];
            }
            return raw.split(',').map(function (item) {
                return item.trim();
            }).filter(Boolean);
        };

        const collectValues = function () {
            const values = [];
            listEl.querySelectorAll('.ea-other-list-row').forEach(function (row) {
                const checkbox = row.querySelector('.ea-other-checkbox');
                const input = row.querySelector('.ea-other-input');
                if (!checkbox || !input) {
                    return;
                }
                const value = (input.value || '').trim();
                if (checkbox.checked && value) {
                    values.push(value);
                }
            });
            hiddenEl.value = values.join(',');
        };

        const createRow = function (value, checked) {
            const col = document.createElement('div');
            col.className = 'col-md-6 ea-other-list-item';

            const row = document.createElement('div');
            row.className = 'ea-other-list-row';
            const formCheck = document.createElement('div');
            formCheck.className = 'form-check d-flex align-items-center gap-2 w-100';

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'form-check-input ea-other-checkbox';
            checkbox.checked = Boolean(checked);

            const input = document.createElement('input');
            input.type = 'text';
            input.className = 'form-control ea-other-input';
            input.placeholder = 'Other';
            input.value = value || '';
            input.disabled = !checkbox.checked;

            checkbox.addEventListener('change', function () {
                input.disabled = !checkbox.checked;
                if (!checkbox.checked) {
                    const wasEmpty = !(input.value || '').trim();
                    input.value = '';
                    const rows = listEl.querySelectorAll('.ea-other-list-row');
                    if (wasEmpty && rows.length > 1) {
                        col.remove();
                    }
                } else {
                    input.disabled = false;
                    input.focus();
                }
                if (!listEl.querySelector('.ea-other-list-row')) {
                    createRow('', false);
                }
                collectValues();
            });

            input.addEventListener('input', function () {
                const rows = listEl.querySelectorAll('.ea-other-list-row');
                const isLast = rows.length && rows[rows.length - 1] === row;
                if (checkbox.checked && input.value.trim() && isLast) {
                    createRow('', false);
                }
                collectValues();
            });

            formCheck.appendChild(checkbox);
            formCheck.appendChild(input);
            row.appendChild(formCheck);
            col.appendChild(row);
            listEl.appendChild(col);
        };

        listEl.innerHTML = '';
        const existing = parseExisting();
        if (existing.length) {
            existing.forEach(function (value) {
                createRow(value, true);
            });
        }
        createRow('', false);
        collectValues();
    };

    initOtherDynamicList('specialty-other-list', 'specialty_other_names');
    initOtherDynamicList('case-other-list', 'case_other_names');
});
